<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/konten') ?>">← Daftar konten</a><?php if ($row && $row['status']==='published'): ?><a class="button button-quiet" href="<?= site_url('informasi/'.$row['slug']) ?>" target="_blank" rel="noopener">Lihat halaman publik ↗</a><?php endif; ?></div>
<section class="form-panel"><div class="form-intro"><span class="panel-overline">MEJA REDAKSI</span><h2><?= $row?'Perbarui informasi':'Informasi baru' ?></h2><p>Gunakan bahasa singkat dan jelas. Tautan regulasi atau kanal sosial sebaiknya menuju sumber resmi.</p></div><form method="post" enctype="multipart/form-data" action="<?= site_url($row?'admin/konten/'.$row['id'].'/simpan':'admin/konten/simpan') ?>"><?= csrf_input() ?><div class="form-grid"><label class="form-full">Judul <span class="required">*</span><input type="text" name="title" maxlength="220" minlength="3" required value="<?= h($row['title']??'') ?>"></label><label>Kategori <span class="required">*</span><select name="category_item_id" required><option value="">Pilih kategori</option><?php foreach ($categories as $c): ?><option value="<?= $c['id'] ?>" <?= ($row['category_item_id']??'')==$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach ($statuses as $code=>$name): ?><option value="<?= $code ?>" <?= ($row['status']??'draft')===$code?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?></select></label><label class="form-full">Ringkasan<textarea name="summary" rows="2" maxlength="1000"><?= h($row['summary']??'') ?></textarea></label><label class="form-full">Isi<textarea name="body" rows="10"><?= h($row['body']??'') ?></textarea></label><label class="form-full">Tautan resmi / sosial<input type="url" name="external_url" maxlength="1000" placeholder="https://..." value="<?= h($row['external_url']??'') ?>"></label><label>Tanggal kegiatan (jika agenda)<input type="date" name="event_on" value="<?= h($row['event_on']??'') ?>"></label><label>Foto kegiatan (JPG, PNG, WebP; maks. 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php if ($row && $row['image_path']): ?><div class="form-full"><img class="content-preview" src="<?= base_url($row['image_path']) ?>" alt="Foto konten"></div><?php endif; ?></div><div class="form-actions"><button class="button button-dark">Simpan konten →</button></div></form></section>
